package main

import("context";"encoding/json";"log";"net/http";"os";"os/signal";"strconv";"syscall";"time";"github.com/divibisoul/Orquestrador-/internal/mesh";"github.com/divibisoul/Orquestrador-/internal/nexus")

type request struct{Goal string `json:"goal"`}
func main(){ctx,stop:=signal.NotifyContext(context.Background(),os.Interrupt,syscall.SIGTERM);defer stop();workers:=4;if v,err:=strconv.Atoi(os.Getenv("NEXUS_WORKERS"));err==nil&&v>0{workers=v};orch:=nexus.NewOrchestrator(workers);pf:=nexus.NewPrefrontal();reg:=mesh.NewRegistry();mux:=http.NewServeMux();mux.Handle("/health",mesh.HealthHandler(reg));mux.HandleFunc("/v1/plan",func(w http.ResponseWriter,r *http.Request){if r.Method!="POST"{w.WriteHeader(http.StatusMethodNotAllowed);return};var q request;if json.NewDecoder(r.Body).Decode(&q)!=nil||q.Goal==""{http.Error(w,"goal required",400);return};plan:=pf.GeneratePlan(q.Goal);d:=pf.Decide(q.Goal,plan,nil);w.Header().Set("content-type","application/json");_ = json.NewEncoder(w).Encode(d)});mux.HandleFunc("/v1/nodes",func(w http.ResponseWriter,_ *http.Request){w.Header().Set("content-type","application/json");_=json.NewEncoder(w).Encode(reg.Snapshot())});srv:=&http.Server{Addr: ":8080",Handler:mux,ReadHeaderTimeout:5*time.Second};go func(){log.Printf("SOUL-NEXUS listening on %s",srv.Addr);if err:=srv.ListenAndServe();err!=nil&&err!=http.ErrServerClosed{log.Fatal(err)}}();<-ctx.Done();shutdown,_:=context.WithTimeout(context.Background(),5*time.Second);defer shutdown();_ = srv.Shutdown(shutdown);_ = orch}
